import { createHash } from "node:crypto";
import type { AiInsights, ProjectDossier } from "@cybercheck/contracts";

// Diagrams for the AI section, generated by code from verified claims (never written by a model),
// so they always parse and only show elements the dossier contains.

const label = (s: string, max = 60) => {
  const t = s.length > max ? `${s.slice(0, max - 1)}…` : s;
  return t.replace(/"/g, "#quot;").replace(/[<>]/g, (c) => (c === "<" ? "#lt;" : "#gt;")).replace(/[{}[\]|`]/g, " ");
};
/** Text after ":" in sequence and state diagrams: no separators or quotes. */
const message = (s: string, max = 70) => (s.length > max ? `${s.slice(0, max - 1)}…` : s).replace(/[;#:"`{}<>]/g, " ").replace(/\s+/g, " ").trim() || "step";
const nid = (prefix: string, identity: string) => `${prefix}_${createHash("sha1").update(identity.toLowerCase().trim()).digest("hex").slice(0, 10)}`;

const SENS_STYLE: Record<string, string> = { secret: "secret", personal: "personal", none: "plain" };

/** Context: people and external systems around the system (C4 level 1). */
function context(ai: AiInsights, d: ProjectDossier): string | null {
  if (!ai.purpose && !d.integrations.length) return null;
  const lines = ["flowchart LR"];
  const sys = nid("sys", "system");
  lines.push(`  ${sys}["${label("This system")}<br/><small>${label(ai.purpose?.summary.split(".")[0] ?? "", 80)}</small>"]`);
  for (const u of ai.purpose?.users ?? []) {
    lines.push(`  ${nid("u", u.name)}(["${label(u.name, 40)}"])`);
    lines.push(`  ${nid("u", u.name)} --> ${sys}`);
  }
  for (const i of d.integrations.filter((x) => x.category !== "http" || x.usedIn.length).slice(0, 20)) {
    lines.push(`  ${nid("ext", i.id)}[("${label(i.name, 40)}<br/><small>${label(i.category)}</small>")]`);
    lines.push(`  ${sys} --> ${nid("ext", i.id)}`);
  }
  return lines.join("\n");
}

/** Data flows grouped by trust boundary, with sensitive data marked. */
function dataFlow(ai: AiInsights): string | null {
  if (!ai.dataFlows.length) return null;
  const lines = ["flowchart LR"];
  const nodes = new Set<string>();
  for (const f of ai.dataFlows) for (const n of [f.from, f.to]) nodes.add(n);
  for (const n of nodes) lines.push(`  ${nid("n", n)}["${label(n, 40)}"]`);
  for (const f of ai.dataFlows) {
    const data = label(`${f.data.slice(0, 3).join(", ")}${f.data.length > 3 ? ", ..." : ""}`, 50);
    const crossing = f.boundary ? ` · crosses ${label(f.boundary, 30)}` : "";
    lines.push(`  ${nid("n", f.from)} -->|"${data}${crossing}"| ${nid("n", f.to)}`);
  }
  // Colour edges by sensitivity.
  ai.dataFlows.forEach((f, i) => {
    const color = f.sensitivity === "secret" ? "#b91c1c" : f.sensitivity === "personal" ? "#b45309" : "#64748b";
    lines.push(`  linkStyle ${i} stroke:${color},stroke-width:${f.sensitivity === "none" ? 1 : 2}px`);
  });
  void SENS_STYLE;
  return lines.join("\n");
}

function stateMachine(m: AiInsights["stateMachines"][number]): string {
  const lines = ["stateDiagram-v2"];
  const id = (s: string) => nid("s", s);
  for (const s of m.states) lines.push(`  state "${label(s, 40)}" as ${id(s)}`);
  for (const t of m.transitions) {
    if (!m.states.includes(t.from)) lines.push(`  state "${label(t.from, 40)}" as ${id(t.from)}`);
    if (!m.states.includes(t.to)) lines.push(`  state "${label(t.to, 40)}" as ${id(t.to)}`);
    lines.push(`  ${id(t.from)} --> ${id(t.to)} : ${message(t.trigger, 50)}`);
  }
  if (m.states[0]) lines.push(`  [*] --> ${id(m.states[0])}`);
  return [...new Set(lines)].join("\n");
}

function sequence(s: AiInsights["sequences"][number]): string {
  const lines = ["sequenceDiagram"];
  const names = [...new Set([...s.participants, ...s.steps.flatMap((x) => [x.from, x.to])])];
  for (const n of names) lines.push(`  participant ${nid("p", n)} as ${message(n, 40)}`);
  for (const st of s.steps.slice(0, 20)) lines.push(`  ${nid("p", st.from)}->>${nid("p", st.to)}: ${message(st.message)}`);
  return lines.join("\n");
}

export function buildAiDiagrams(ai: AiInsights, d: ProjectDossier): Record<string, string> {
  const out: Record<string, string> = {};
  const c = context(ai, d);
  if (c) out.context = c;
  const f = dataFlow(ai);
  if (f) out.data_flow = f;
  ai.stateMachines.forEach((m) => (out[`state:${m.id}`] = stateMachine(m)));
  ai.sequences.forEach((s) => (out[`sequence:${s.id}`] = sequence(s)));
  return out;
}
